const A=()=>document.getElementById('A');
const set=v=>{const i=A().querySelector('[data-search]');i.value=v;i.dispatchEvent(new Event('input'))};
const pick=i=>A().querySelector(`tr.row[data-i="${i}"]`).click();
const key=(k,o={})=>A().dispatchEvent(new KeyboardEvent('keydown',Object.assign({key:k,bubbles:true},o)));
const dark=()=>{document.body.dataset.theme='dark'};
const size=(w,h)=>{document.querySelector(`.szb[data-w="${w}"][data-h="${h}"]`).click()};
const wait=ms=>new Promise(r=>setTimeout(r,ms));
document.documentElement.style.scrollBehavior='auto';
